    adj = defaultdict(list)
    for u, v in edges:
        adj[u].append(v)

    # Helper BFS that returns distance dict (node -> distance from start)
    def bfs(start, graph):
        dist = {start: 0}
        q = deque([start])
        while q:
            cur = q.popleft()
            for nxt in graph.get(cur, []):
                if nxt not in dist:
                    dist[nxt] = dist[cur] + 1
                    q.append(nxt)
        return dist

    # Case 1: source and target are different -> simple shortest path
    if source != target:
        dist = bfs(source, adj)
        return dist.get(target, -1)

    # Case 2: source == target -> need shortest positive-length cycle
    # Build reversed graph to compute distances *to* the source in the original graph
    rev_adj = defaultdict(list)
    for u, v in edges:
